t_text23]]},["rlt_text24"]={["arg1"]=[[文本输出]],["arg2"]=[[你抄起吴刚斧，砍在云母树之上，云母树终于被你砍倒了，云母树之中有一团星光掉了出来。]],["id"]=[[rlt_text24]]},["rlt_text25"]={["arg1"]=[[文本输出]],["arg2"]=[[你运起轻功跳上金果树摘了个果子下来。]],["id"]=[[rlt_text25]]},["rlt_text26"]={["arg1"]=[[文本输出]],["arg2"]=[[你将拖来的桃源树放在天河旁，准备度过天河。]],["id"]=[[rlt_text26]]},["rlt_text27"]={["arg1"]=[[文本输出]],["arg2"]=[[你被一个波浪打了回来，之前的辛苦都化为乌有。]],["id"]=[[rlt_text27]]},["rlt_text28"]={["arg1"]=[[文本输出]],["arg2"]=[[你乘着桃源木，终于是抵达了对岸。]],["id"]=[[rlt_text28]]},["rlt_text29"]={["arg1"]=[[文本输出]],["arg2"]=[[你扒开红荆林向前走，但这红荆林似乎无穷无尽。]],["id"]=[[rlt_text29]]},["rlt_text3"]={["arg1"]=[[文本输出]],["arg2"]=[[HIB天空中有一群群喜鹊向西南鹊桥方向飞去，十分壮观。]],["id"]=[[rlt_text3]]},["rlt_text30"]={["arg1"]=[[文本输出]],["arg2"]=[[你扒开红荆林走了出来，但浑身上下都被刺得满是伤痕。]],["id"]=[[rlt_text30]]},["rlt_text31"]={["arg1"]=[[文本输出]],["arg2"]=[[你用金丝剪剪开了红荆林。]],["id"]=[[rlt_text31]]},["rlt_text32"]={["arg1"]=[[文本输出]],["arg2"]=[[老头不收你的东西。]],["id"]=[[rlt_text32]]},["rlt_text33"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL老头:嗯，不错不错，这果子不错。]],["id"]=[[rlt_text33]]},["rlt_text34"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL老头:呸，什么果子，真是难吃，你能找点能吃的东西来么？]],["id"]=[[rlt_text34]]},["rlt_text35"]={["arg1"]=[[文本输出]],["arg2"]=[[你握住斧把，这吴刚斧看似很重，但却极轻，颇为奇异。]],["id"]=[[rlt_text35]]},["rlt_text36"]={["arg1"]=[[文本输出]],["arg2"]=[[一头老黄牛叫住了你，向你走来。]],["id"]=[[rlt_text36]]},["rlt_text37"]={["arg1"]=[[文本输出]],["arg2"]=[[年轻女子不收你的东西。]],["id"]=[[rlt_text37]]},["rlt_text38"]={["arg1"]=[[文本输出]],["arg2"]=[[年轻女子收下了你的黄牛皮。]],["id"]=[[rlt_text38]]},["rlt_text39"]={["arg1"]=[[文本输出]],["arg2"]=[[年轻女子收下了你的织女梭。]],["id"]=[[rlt_text39]]},["rlt_text4"]={["arg1"]=[[文本输出]],["arg2"]=[[HIM天空中星云汇聚，看来离牛郎织女相会的时间已经不远了。]],["id"]=[[rlt_text4]]},["rlt_text40"]={["arg1"]=[[文本输出]],["arg2"]=[[HIC你拨动机关锁，按下了开关，只听一声爆响，白玉台应声而碎，一颗星辰从玉台中冲出飞向西面。]],["id"]=[[rlt_text40]]},["rlt_text41"]={["arg1"]=[[文本输出]],["arg2"]=[[你拨动机关锁，但毫无反应，似乎是输入不正确。]],["id"]=[[rlt_text41]]},["rlt_text42"]={["arg1"]=[[文本输出]],["arg2"]=[[你将手伸向星光，星光发出道道流光猛然击向了你。]],["id"]=[[rlt_text42]]},["rlt_text43"]={["arg1"]=[[文本输出]],["arg2"]=[[HIC你躲过了所有的流光，那团耀眼的星光也渐渐暗淡，随后飞往了西北方。]],["id"]=[[rlt_text43]]},["rlt_text44"]={["arg1"]=[[文本输出]],["arg2"]=[[你看到一群喜鹊朝着东南方飞去。]],["id"]=[[rlt_text44]]},["rlt_text45"]={["arg1"]=[[文本输出]],["arg2"]=[[北斗蔓中传来喜鹊的叫声。]],["id"]=[[rlt_text45]]},["rlt_text46"]={["arg1"]=[[文本输出]],["arg2"]=[[翻找斗翠箱，从箱中找出一把小木锤。]],["id"]=[[rlt_text46]]},["rlt_text47"]={["arg1"]=[[文本输出]],["arg2"]=[[翻找斗翠箱，从箱中找出一把镰刀。]],["id"]=[[rlt_text47]]},["rlt_text48"]={["arg1"]=[[文本输出]],["arg2"]=[[翻找斗翠箱，从箱中找出一把拨浪鼓。]],["id"]=[[rlt_text48]]},["rlt_text49"]={["arg1"]=[[文本输出]],["arg2"]=[[翻找斗翠箱，从箱中找出一把袜子。]],["id"]=[[rlt_text49]]},["rlt_text5"]={["arg1"]=[[文本输出]],["arg2"]=[[HIR朵朵彩云向鹊桥方向飘去，大片的晚霞聚拢，景象十分迷人，离相会的时间已是越来越近了。]],["id"]=[[rlt_text5]]},["rlt_text50"]={["arg1"]=[[文本输出]],["arg2"]=[[HIC你用镰刀轻松地割开了北斗蔓，放出了里面困着的喜鹊。]],["id"]=[[rlt_text50]]},["rlt_text51"]={["arg1"]=[[文本输出]],["arg2"]=[[你打开包裹，包裹内只有一张字条和一把铲子。
字条上写着:
天临映太清，
涯文有雅思。
海屋银为栋，
角怨星芒动。
你将铲子捡拾起来。]],["id"]=[[rlt_text51]]},["rlt_text52"]={["arg1"]=[[文本输出]],["arg2"]=[[土堆坚硬无比，你用双手刨了一刨便放弃了。]],["id"]=[[rlt_text52]]},["rlt_text53"]={["arg1"]=[[文本输出]],["arg2"]=[[你一阵乱挖，什么东西也没挖到。]],["id"]=[[rlt_text53]]},["rlt_text54"]={["arg1"]=[[文本输出]],["arg2"]=[[你一铲子下去，碰到一个坚硬的物件，小心翼翼地挖开，竟然是一个白玉瓶。]],["id"]=[[rlt_text54]]},["rlt_text55"]={["arg1"]=[[文本输出]],["arg2"]=[[HIC你打开白玉瓶，放出了里面困着的彩云。]],["id"]=[[rlt_text55]]},["rlt_text56"]={["arg1"]=[[文本输出]],["arg2"]=[[百星谭中倒映着月亮星辰的影子，璀璨夺目。]],["id"]=[[rlt_text56]]},["rlt_text57"]={["arg1"]=[[文本输出]],["arg2"]=[[你想用手去捧起里面的星辰，但试了很多次都徒劳无获。]],["id"]=[[rlt_text57]]},["rlt_text58"]={["arg1"]=[[文本输出]],["arg2"]=[[你见到妆镜台上有一把铜镜，就把它拿了下来。]],["id"]=[[rlt_text58]]},["rlt_text59"]={["arg1"]=[[文本输出]],["arg2"]=[[你登上了望月台，月光如泻洒在你身上。]],["id"]=[[rlt_text59]]},["rlt_text6"]={["arg1"]=[[文本输出]],["arg2"]=[[HIY星光聚合，银白色的天河倒挂于星空之中，看来牛郎织女即将相会了。]],["id"]=[[rlt_text6]]},["rlt_text60"]={["arg1"]=[[文本输出]],["arg2"]=[[你登上了望月台，月光凝照在铜镜之上，铜镜似乎产生了变化。]],["id"]=[[rlt_text60]]},["rlt_text61"]={["arg1"]=[[文本输出]],["arg2"]=[[HIC你将月光镜放入水中，星辰被吸引过来，最终离开水面浮向空中。]],["id"]=[[rlt_text61]]},["rlt_text62"]={["arg1"]=[[文本输出]],["arg2"]=[[鸟居里面居住着喜鹊，但是洞口太小了，你够不到里面。]],["id"]=[[rlt_text62]]},["rlt_text63"]={["arg1"]=[[文本输出]],["arg2"]=[[你身上什么都没有，喂它吃土吗？]],["id"]=[[rlt_text63]]},["rlt_text64"]={["arg1"]=[[文本输出]],["arg2"]=[[你用力拍打松树，掉下来一些松果，剥开来便是松子。]],["id"]=[[rlt_text64]]},["rlt_text65"]={["arg1"]=[[文本输出]],["arg2"]=[[喜鹊朝松子过来了。]],["id"]=[[rlt_text65]]},["rlt_text66"]={["arg1"]=[[文本输出]],["arg2"]=[[喜鹊很快又飞回了鸟居。]],["id"]=[[rlt_text66]]},["rlt_text67"]={["arg1"]=[[文本输出]],["arg2"]=[[HIC你抓住了喜鹊，让它吃饱后就飞走了。]],["id"]=[[rlt_text67]]},["rlt_text68"]={["arg1"]=[[文本输出]],["arg2"]=[[你一阵乱挖，什么东西也没挖到。铲子却被你不小心折断了。]],["id"]=[[rlt_text68]]},["rlt_text69"]={["arg1"]=[[文本输出]],["arg2"]=[[你一铲子下去，碰到一个坚硬的物件，小心翼翼地挖开，竟然是一个白玉瓶。
但铲子被你不小心折断了。]],["id"]=[[rlt_text69]]},["rlt_text7"]={["arg1"]=[[文本输出]],["arg2"]=[[HIM喜鹊搭成鹊桥，星云高悬，天河倒挂，终是到了牛郎织女相会的时间，你也跟着来往的喜鹊来到了鹊桥之上。]],["id"]=[[rlt_text7]]},["rlt_text70"]={["arg1"]=[[文本输出]],["arg2"]=[[你拾起一把金丝剪。]],["id"]=[[rlt_text70]]},["rlt_text71"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL织女:这薄礼是夫君与我的一份心意，还请少侠收下。
YEL织女:少侠，夫君与我只有一天的时间能够相聚，能不能请少侠…
CYN织女话音未落，便感到头晕目眩，再清醒时又到了熟悉的地方。]],["id"]=[[rlt_text71]]},["rlt_text72"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL中年文士：你果真不凡，那我就助你一臂之力！
HIC中年文士大手一挥，一颗璀璨的星光飞向了西北方！
CYN待你回过神来，中年文士已是不见了！]],["id"]=[[rlt_text72]]},["rlt_text73"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL中年文士:不对不对，你答错了。]],["id"]=[[rlt_text73]]},["rlt_text74"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL中年文士:这么多次都无法答出我的问题，哎！]],["id"]=[[rlt_text74]]},["rlt_text75"]={["arg1"]=[[文本输出]],["arg2"]=[[你读着纸条上的文字，上面写着:坤艮兑坎乾离巽震。]],["id"]=[[rlt_text75]]},["rlt_text76"]={["arg1"]=[[文本输出]],["arg2"]=[[你看着这纸条上的文字，晦涩难懂，想了许久也没有头绪。]],["id"]=[[rlt_text76]]},["rlt_text77"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL中年文士：哈哈，答得不错，再来再来！]],["id"]=[[rlt_text77]]},["rlt_text78"]={["arg1"]=[[文本输出]],["arg2"]=[[你走入云道，也不知走了多久，终于是走到了尽头，你一抬头，天上满是喜鹊，正在向东南而飞，你环顾四周，这里似乎是那传说中的鹊桥附近。]],["id"]=[[rlt_text78]]},["rlt_text79"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN年轻男子：一日不见，思之如狂。我二人能重逢，多亏了那名年轻人。
CYN年轻女子:是啊，多亏他我们才能于此执手相看。相逢虽短，却愿再不分离。
CYN周围的景物突然开始倒退，眼前的男女也离你越来越远，你晕了过去。]],["id"]=[[rlt_text79]]},["rlt_text8"]={["arg1"]=[[文本输出]],["arg2"]=[[你看到一群喜鹊朝着东南方飞去。]],["id"]=[[rlt_text8]]},["rlt_text80"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text80]]},["rlt_text81"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text81]]},["rlt_text9"]={["arg1"]=[[文本输出]],["arg2"]=[[你仔细查看这张缠云网，这缠云网十分坚固，网中喜鹊叽叽喳喳地叫着，似乎想要飞出这里。]],["id"]=[[rlt_text9]]},["rlt_textout1"]={["arg1"]=[[弹出文本]],["arg2"]=[[红荆林挡住了你的去路。]],["id"]=[[rlt_textout1]]}}00000